function dateOnly(d){let x=d?new Date(d+'T12:00:00'):new Date();return isNaN(x)?new Date():x}
function isoDate(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function addDays(d,n){let x=new Date(d);x.setDate(x.getDate()+n);return x}
function weekRange(kind,anchor){let d=dateOnly(anchor||today()),day=d.getDay();if(kind==='weekday'){let delta=day===0?-6:1-day,start=addDays(d,delta),end=addDays(start,4);return[start,end]}let delta=day===0?-1:6-day,start=addDays(d,delta),end=addDays(start,1);return[start,end]}
function priorityTitle(kind){let meta=state.priorityMeta[kind]||{},[a,b]=weekRange(kind,meta.anchor||today());return `${kind==='weekend'?'WEEKEND':'WEEKDAY'} PRIORITIES — ${fmtDate(isoDate(a))} – ${fmtDate(isoDate(b))}`}
function syncPriorityList(kind){let existing=new Map((state.priorities[kind]||[]).map(p=>[p.tool,p])),tools=morningSortTools(workloadTools());let rows=tools.map((t,i)=>{let p=existing.get(t.id)||{};return{tool:t.id,priority:p.priority||i+1,assignment:p.assignment||t.driver||'Unassigned',notes:p.notes||'',autoScore:p.autoScore||0}});state.priorities[kind]=rows;return rows}
function volunteerTable(day,arr){return `<div class="volunteer-panel"><div class="volunteer-head"><b>${day.toUpperCase()} VOLUNTEERS</b><button class="btn" type="button" data-add-volunteer="${day.toLowerCase()}">+ ADD ${day.toUpperCase()} VOLUNTEER</button></div>${arr.map((v,i)=>`<div class="volunteer-row" data-volunteer="${day.toLowerCase()}-${i}"><input data-vf="name" placeholder="Name" value="${esc(v.name||'')}"><input data-vf="hours" placeholder="Hours" value="${esc(v.hours||'')}"><textarea data-vf="notes" placeholder="Notes">${esc(v.notes||'')}</textarea><button type="button" class="btn danger-mini" data-remove-volunteer="${day.toLowerCase()}" data-volunteer-index="${i}">×</button></div>`).join('')||'<p class="muted">No volunteers entered.</p>'}</div>`}
function volunteerDisplay(day,arr){return `<div class="volunteer-panel"><div class="volunteer-head"><b>${day.toUpperCase()} VOLUNTEERS</b></div>${arr.map(v=>`<div class="volunteer-display-row"><b>${esc(v.name||'—')}</b><span>${esc(v.hours||'')}</span><span>${esc(v.notes||'')}</span></div>`).join('')||'<p class="muted">No volunteers entered.</p>'}</div>`}
function priorityView(kind,heading=true){let list=syncPriorityList(kind),map=new Map(workloadTools().map(t=>[t.id,t])),meta=state.priorityMeta[kind]||{};let vols=kind==='weekend'?`<div class="volunteer-display">${volunteerDisplay('Saturday',meta.saturday||[])}${volunteerDisplay('Sunday',meta.sunday||[])}</div>`:'';return `${heading?centerPageTitle((kind==='weekend'?'WEEKEND':'WEEKDAY')+' PRIORITIES'):''}<section class="panel priority-frame">${vols}${list.length?`<table class="data-table"><thead><tr><th>Priority</th><th>UTID</th><th>Model</th><th>Sales Order</th><th>Customer</th><th>MFG Ship Date</th><th>Cleanroom</th><th>Tool Assignment</th><th>Notes</th></tr></thead><tbody>${[...list].sort((a,b)=>a.priority-b.priority).map(p=>{let t=map.get(p.tool)||{};return `<tr class="clickrow" data-tool="${esc(p.tool)}"><td><b>${p.priority}</b></td><td>${esc(p.tool)}</td><td>${esc(t.model||'')}</td><td>${esc(t.salesOrder||'')}</td><td>${esc(t.customer||'')}</td><td>${esc(fmtDate(t.shipDate||''))}</td><td>${esc(t.cleanroom||'')}</td><td>${esc(p.assignment||t.driver||'')}</td><td class="multiline-cell">${esc(p.notes||'').replace(/\n/g,'<br>')}</td></tr>`}).join('')}</tbody></table>`:'<p>No active tools.</p>'}</section>`}
function priorityEdit(kind){syncPriorityList(kind);let current=new Map((state.priorities[kind]||[]).map(p=>[p.tool,p])),meta=state.priorityMeta[kind]||{};let weekend=kind==='weekend'?`<div class="volunteer-editor">${volunteerTable('Saturday',meta.saturday||[])}${volunteerTable('Sunday',meta.sunday||[])}</div>`:'';return `<section class="panel priority-frame"><div class="priority-datebar"><label>${kind==='weekend'?'Weekend Date':'Week Date'}<input id="priorityAnchor" type="date" value="${esc(meta.anchor||today())}"></label><b id="priorityRangeTitle">${esc(priorityTitle(kind))}</b></div>${weekend}<div class="priority-edit-wrap"><table class="data-table priority-edit priority-edit-full"><thead><tr><th>UTID / Tool</th><th>Priority</th><th>Model</th><th>Sales Order</th><th>Customer</th><th>MFG Ship Date</th><th>Cleanroom</th><th>Tool Assignment</th><th>Notes</th></tr></thead><tbody>${morningSortTools(workloadTools()).map(t=>{let p=current.get(t.id)||{};return `<tr data-priority="${esc(t.id)}"><td><b>${esc(t.id)}</b><small>${esc(String(t.codename||'').toUpperCase())}</small></td><td><input data-pf="priority" type="number" min="1" value="${esc(p.priority||'')}"></td><td><input data-pf="model" value="${esc(t.model||'')}" readonly></td><td><input data-pf="salesOrder" value="${esc(t.salesOrder||'')}"></td><td><input data-pf="customer" value="${esc(t.customer||'')}"></td><td><input data-pf="shipDate" type="date" value="${esc(t.shipDate||'')}"></td><td><input data-pf="cleanroom" value="${esc(t.cleanroom||'')}"></td><td><input data-pf="assignment" value="${esc(p.assignment||t.driver||'')}"></td><td><textarea data-pf="notes" rows="3" placeholder="Enter multiple lines of notes...">${esc(p.notes||'')}</textarea></td></tr>`}).join('')}</tbody></table></div></section>`}
function packingMilestoneSummary(t){let c=t.shipping?.completed||{},force=t.toolStatus==='Shipped',short={subsystems:'SUBS',accessories:'ACC',cables:'CABLES',mat:'MST',is:'IS'};return shippingKeys(t).map(([k])=>{let done=force||!!c[k];return `<span class="milestone-pill ${done?'done':''}">${done?'✓':'○'} ${short[k]||k.toUpperCase()}</span>`}).join('')}
function shippingView(operationsMode=false){let a=activeTools().filter(t=>operationsMode?['FI','Engineering','Powered Down','Packing'].includes(t.toolStatus):true);return `${operationsMode?'':centerPageTitle(state.quarter+' SHIPPING SCHEDULE')}<section class="panel shipping-frame"><table class="data-table shipping-overview"><thead><tr><th>Tool</th><th>Model</th><th>FI Status</th><th>Ship Date</th><th>Shipping Status</th><th>Shipping Progress</th><th>Packing Progress</th>${operationsMode?'':'<th>Notes</th><th>Update</th>'}</tr></thead><tbody>${a.map(t=>{let p=shippingProgress(t),ss=shippingLabel(t),enabled=t.toolStatus==='Packing';return `<tr class="clickrow" data-tool="${esc(t.id)}"><td><b>${esc(t.id)}</b></td><td>${esc(t.model)}</td><td>${esc(t.toolStatus)}</td><td>${esc(shipDayDate(t.shipDate)||'—')}</td><td><span class="shipping-state ${ss.css}">${ss.label}</span></td><td>${['WAITING FI','IN FI','POWERED DOWN'].includes(ss.label)?(t.toolStatus==='Powered Down'?'0%':'—'):`<div class="track"><div class="fill green" style="width:${p}%"></div></div><small>${p}%</small>`}</td><td><div class="milestone-strip">${packingMilestoneSummary(t)}</div></td>${operationsMode?'':`<td class="shipping-notes-cell" title="${esc(t.shipping?.notes||'')}">${esc(t.shipping?.notes||'—')}</td><td>${enabled?`<button class="btn handoff-open" data-handoffs="${esc(t.id)}">UPDATE PROGRESS</button>`:`<span class="muted">${esc(shippingStep(t))}</span>`}</td>`}</tr>`}).join('')}</tbody></table></section>`}


function shippingEdit(){let a=activeTools();return `<section class="panel shipping-frame"><table class="data-table shipping-edit-table"><thead><tr><th>Tool</th><th>Schedule Status</th><th>Sent</th><th>Milestones</th><th>Notes</th></tr></thead><tbody>${a.map(t=>`<tr data-shipping="${esc(t.id)}"><td><b>${esc(t.id)}</b><br><small>${esc(t.toolStatus)}</small></td><td><select data-sf="scheduleStatus">${selectOptions(['Not Started','Created','Sent','Active','Complete'],t.shipping.scheduleStatus)}</select></td><td><select data-sf="scheduleSent">${selectOptions(['No','Yes'],t.shipping.scheduleSent?'Yes':'No')}</select></td><td><div class="shipping-milestone-editor">${shippingKeys(t).map(([k,l])=>milestoneEditor(t,k,l)).join('')}</div></td><td><textarea data-sf="notes">${esc(t.shipping.notes||'')}</textarea></td></tr>`).join('')}</tbody></table></section>`}
function milestoneEditor(t,k,label){let c=t.shipping?.completed||{},planned=t.shipping?.[k]||'',actual=c[k]||'';return `<div class="milestone-edit-row"><label class="milestone-check"><input type="checkbox" data-ms-complete="${k}" ${actual?'checked':''}> ${esc(label)}</label><label>Planned <input type="date" data-ms-plan="${k}" value="${esc(planned)}"></label><label>Actual <input type="date" data-ms-actual="${k}" value="${esc(actual)}"></label></div>`}
function meetingHistory(filter=''){let rows=state.meetings.filter(m=>!filter||m.type===filter);return `${centerPageTitle(filter?filter.toUpperCase():'MEETINGS')}<section class="panel meeting-history">${rows.map(m=>`<div class="ref-row clickrow" data-search-meeting="${esc(m.id)}"><b>${esc(m.type)}</b><span>${esc(fmtDate(m.date))} · ${esc(m.tool||m.status||'')}</span></div>`).join('')||'<p>No meetings saved yet.</p>'}</section>`}
function meetingHome(){return meetingHistory()}

function morningDraftId(type,date=today()){return `draft-${type}-${date}`}
function findMorningDraft(type){let id=morningDraftId(type,today());return state.meetings.find(x=>x.id===id&&x.status==='Draft')||null}
function normalizeMorningAction(a){if(!a)return {id:uid('ma'),type:'Action',text:'',owner:'',due:''};return {id:a.id||uid('ma'),type:a.type||'Action',text:a.text||'',owner:a.owner||'',due:a.due||''}}
function normalizeMorningDraft(m,tools){m=clone(m||{});m.toolOrder=Array.isArray(m.toolOrder)&&m.toolOrder.length?m.toolOrder:tools.map(t=>t.id);m.toolNotes=m.toolNotes||{};m.toolActions=m.toolActions||{};tools.forEach(t=>{let a=m.toolActions[t.id];if(!Array.isArray(a))a=a&&typeof a==='object'?[a]:[];m.toolActions[t.id]=a.map(normalizeMorningAction)});let ga=m.generalActions;if(!Array.isArray(ga))ga=m.generalAction&&m.generalAction.text?[m.generalAction]:[];m.generalActions=ga.map(normalizeMorningAction);return m}
function morningMeetingTools(m){return dailyOrderedTools()}
function startMorningMeeting(){let type=route.sub==='weekend'?'Weekend Morning Meeting':'Weekday Morning Meeting',tools=dailyOrderedTools(),saved=findMorningDraft(type);mode='morningMeeting';meetingDraft=normalizeMorningDraft(saved||{type,date:today(),startedAt:nowISO(),onCallManager:'',onCallMDE:'',onCallPlanner:'',generalNotes:'',toolNotes:Object.fromEntries(tools.map(t=>[t.id,''])),toolActions:{},generalActions:[],toolOrder:tools.map(t=>t.id)},tools);dirty=false;render()}
function morningActionRows(actions,scope){actions=Array.isArray(actions)?actions:[];return `<div class="morning-action-list">${actions.map((a,i)=>`<div class="morning-action-row" data-mm-task-scope="${esc(scope)}" data-mm-task-index="${i}"><select data-mm-task-field="type">${selectOptions(['Action','Reminder','Alert'],a.type||'Action')}</select><input data-mm-task-field="text" placeholder="Task / reminder / alert" value="${esc(a.text||'')}"><input data-mm-task-field="owner" placeholder="Owner" value="${esc(a.owner||'')}"><input data-mm-task-field="due" type="date" value="${esc(a.due||'')}"><button type="button" class="btn danger-mini" data-mm-remove-task="${i}" data-mm-scope="${esc(scope)}">×</button></div>`).join('')}</div>`}
function morningMeetingForm(m){let weekend=m.type.startsWith('Weekend'),tools=morningMeetingTools(m);m=normalizeMorningDraft(m,tools);meetingDraft=m;let oncall=weekend?`<div class="oncall-grid"><label>On-Call Manager<input id="mm-manager" value="${esc(m.onCallManager||'')}"></label><label>On-Call MDE<input id="mm-mde" value="${esc(m.onCallMDE||'')}"></label><label>On-Call Planner<input id="mm-planner" value="${esc(m.onCallPlanner||'')}"></label></div>`:'';return `<section class="panel morning-meeting"><div class="meeting-title">${esc(m.type.toUpperCase())} · ${esc(fmtDate(m.date))}${findMorningDraft(m.type)?' · SAVED DRAFT':''}</div>${oncall}${tools.map((t,i)=>{let actions=m.toolActions?.[t.id]||[];return `<article class="meeting-tool"><div class="meeting-tool-head"><b>${i+1}. ${esc(t.id)} · ${esc(String(t.codename||'').toUpperCase())} · ${esc(t.model)}</b><span>${esc(t.toolStatus)} · ${esc(performance(t)[0])}</span></div><div class="meeting-snapshot"><span>Checklist: <b>${esc(t.currentChecklist)}</b></span><span>Customer: <b>${esc(t.customer)}</b></span><span>Ship: <b>${esc(fmtDate(t.shipDate))}</b></span><span>Driver: <b>${esc(t.driver)}</b></span><span>Lamp: <b>${Number(t.lamp)||0}</b></span></div><label>Tool Meeting Notes<textarea data-mm-note="${esc(t.id)}">${esc(m.toolNotes?.[t.id]||'')}</textarea></label><div class="morning-actions-head"><b>TASKS / REMINDERS / ALERTS</b><button type="button" class="btn" data-mm-add-task data-mm-scope="${esc(t.id)}">+ ADD TASK</button></div>${morningActionRows(actions,t.id)}</article>`}).join('')}<div class="general-meeting"><label>GENERAL MEETING NOTES<textarea id="mm-general">${esc(m.generalNotes||'')}</textarea></label><div class="morning-actions-head"><b>GENERAL TASKS / REMINDERS / ALERTS</b><button type="button" class="btn" data-mm-add-task data-mm-scope="general">+ ADD TASK</button></div>${morningActionRows(m.generalActions||[],'general')}</div></section>`}
function collectMorningMeeting(){let m=meetingDraft;if(!m)return;let tools=morningMeetingTools(m);m.date=m.date||today();m.onCallManager=document.querySelector('#mm-manager')?.value||m.onCallManager||'';m.onCallMDE=document.querySelector('#mm-mde')?.value||m.onCallMDE||'';m.onCallPlanner=document.querySelector('#mm-planner')?.value||m.onCallPlanner||'';m.generalNotes=document.querySelector('#mm-general')?.value||'';m.toolNotes=m.toolNotes||{};document.querySelectorAll('[data-mm-note]').forEach(x=>m.toolNotes[x.dataset.mmNote]=x.value);m.toolActions=m.toolActions||{};tools.forEach(t=>{m.toolActions[t.id]=[...document.querySelectorAll(`[data-mm-task-scope="${CSS.escape(t.id)}"]`)].map(r=>({id:m.toolActions?.[t.id]?.[Number(r.dataset.mmTaskIndex)]?.id||uid('ma'),type:r.querySelector('[data-mm-task-field="type"]')?.value||'Action',text:r.querySelector('[data-mm-task-field="text"]')?.value||'',owner:r.querySelector('[data-mm-task-field="owner"]')?.value||'',due:r.querySelector('[data-mm-task-field="due"]')?.value||''})).filter(a=>a.text||a.owner||a.due)});m.generalActions=[...document.querySelectorAll('[data-mm-task-scope="general"]')].map(r=>({id:m.generalActions?.[Number(r.dataset.mmTaskIndex)]?.id||uid('ma'),type:r.querySelector('[data-mm-task-field="type"]')?.value||'Action',text:r.querySelector('[data-mm-task-field="text"]')?.value||'',owner:r.querySelector('[data-mm-task-field="owner"]')?.value||'',due:r.querySelector('[data-mm-task-field="due"]')?.value||''})).filter(a=>a.text||a.owner||a.due);m.toolOrder=Array.isArray(m.toolOrder)&&m.toolOrder.length?m.toolOrder:tools.map(t=>t.id)}
function saveMorningMeeting(complete=false){collectMorningMeeting();let m=meetingDraft;if(!m)return;let actions=[],severityFor=type=>type==='Alert'?'Critical':type==='Reminder'?'Reminder':'Attention';Object.entries(m.toolActions||{}).forEach(([tool,list])=>(Array.isArray(list)?list:[]).forEach(a=>{if(a.text)actions.push({id:uid('act'),severity:severityFor(a.type),tool,text:a.text,owner:a.owner,due:a.due,status:'Open',createdAt:nowISO(),sourceMeeting:m.type,sourceTaskId:a.id})}));(m.generalActions||[]).forEach(a=>{if(a.text)actions.push({id:uid('act'),severity:severityFor(a.type),tool:'',text:a.text,owner:a.owner,due:a.due,status:'Open',createdAt:nowISO(),sourceMeeting:m.type,sourceTaskId:a.id})});let draftId=morningDraftId(m.type,m.date||today());if(complete){state.meetings=state.meetings.filter(x=>x.id!==draftId);let completedId=`morning-${m.type?.toLowerCase().includes('weekend')?'weekend':'weekday'}-${m.date||today()}`;state.meetings=state.meetings.filter(x=>x.id!==completedId);let existingActionKeys=new Set(state.actions.map(a=>`${a.sourceMeeting||''}|${a.sourceTaskId||''}`));state.actions.unshift(...actions.filter(a=>!existingActionKeys.has(`${a.sourceMeeting||''}|${a.sourceTaskId||''}`)));let mt=clone(morningMeetingTools(m));state.meetings.unshift({...clone(m),id:completedId,endedAt:nowISO(),status:'Complete',toolSnapshots:mt});let sid=`${m.type?.toLowerCase().includes('weekend')?'weekend':'weekday'}-${m.date||today()}`;state.statusRecords=state.statusRecords.filter(x=>x.id!==sid);state.statusRecords.unshift({id:sid,kind:m.type?.toLowerCase().includes('weekend')?'Weekend Morning Status':'Weekday Morning Status',date:m.date||today(),savedAt:nowISO(),tools:mt});saveState('MORNING MEETING COMPLETED');mode='view';meetingDraft=null;render()}else{let rec={...clone(m),id:draftId,savedAt:nowISO(),status:'Draft'};let i=state.meetings.findIndex(x=>x.id===draftId);if(i>=0)state.meetings[i]=rec;else state.meetings.unshift(rec);saveState('MORNING MEETING SAVED');toast('✓ MORNING MEETING SAVED — RESUME AVAILABLE')}}
function meetingTaskRows(m){m.tasks=Array.isArray(m.tasks)?m.tasks:[];return `<div class="meeting-task-list">${m.tasks.map((x,i)=>`<div class="meeting-task-row" data-meeting-task="${i}"><b>TASK ${i+1}</b><input data-mtf="text" value="${esc(x.text||'')}" placeholder="Action / task"><input data-mtf="owner" value="${esc(x.owner||'')}" placeholder="Owner"><input data-mtf="due" type="date" value="${esc(x.due||'')}"><button class="btn" data-remove-meeting-task="${i}">×</button></div>`).join('')}</div>`}
function captureMeetingForm(){if(!meetingDraft)return;let v=id=>document.querySelector(id)?.value||'';meetingDraft.tool=v('#mf-tool');meetingDraft.nc=v('#mf-nc');meetingDraft.date=v('#mf-date')||today();meetingDraft.owner=v('#mf-owner');meetingDraft.notes=v('#mf-notes');meetingDraft.poa=v('#mf-poa');meetingDraft.disposition=v('#mf-disposition');meetingDraft.tasks=[...document.querySelectorAll('[data-meeting-task]')].map(r=>({id:r.dataset.taskId||uid('task'),text:r.querySelector('[data-mtf="text"]')?.value||'',owner:r.querySelector('[data-mtf="owner"]')?.value||'',due:r.querySelector('[data-mtf="due"]')?.value||''})).filter(x=>x.text||x.owner||x.due)}
function meetingForm(m){let escMode=m.type==='Escalation Meeting';m.tasks=Array.isArray(m.tasks)?m.tasks:[];return `<section class="panel"><h2>${esc(m.type).toUpperCase()}</h2><div class="form-grid">${escMode?selField('Tool','mf-tool',activeTools().map(t=>option(t.id,`${t.id} · ${t.codename}`,m.tool)).join(''),m.tool):''}${escMode?field('NC','mf-nc',m.nc):''}${field('Date','mf-date',m.date||today(),'date')}${field('Meeting Lead / Facilitator','mf-owner',m.owner||'')}<div class="field span4"><label>Meeting Notes</label><textarea id="mf-notes">${esc(m.notes||'')}</textarea></div>${escMode?`<div class="field span4"><label>POA / Decision</label><textarea id="mf-poa">${esc(m.poa||'')}</textarea></div>${selField('FI Disposition','mf-disposition',selectOptions(['Continue FI','Continue with Restrictions','FI Blocked','TBD'],m.disposition||'TBD'),m.disposition||'TBD')}`:''}<div class="field span4"><div class="panel-head"><label>ACTION TASKS</label><button class="btn" type="button" data-add-meeting-task>+ ADD TASK</button></div>${meetingTaskRows(m)}</div></div></section>`}

function actionView(){let all=state.actions||[],open=all.filter(a=>a.status!=='Complete'),norm=x=>String(x||'Attention').toLowerCase(),counts={critical:open.filter(a=>norm(a.severity)==='critical').length,attention:open.filter(a=>norm(a.severity)==='attention').length,reminder:open.filter(a=>norm(a.severity)==='reminder').length,information:open.filter(a=>norm(a.severity)==='information').length};let list=route.sub==='history'?all.filter(a=>a.status==='Complete'):route.sub==='open'?open:open.filter(a=>norm(a.severity)===String(route.sub||'').toLowerCase());let card=a=>`<div class="action-card ${norm(a.severity)} clickrow" data-edit-action="${esc(a.id)}"><div class="panel-head"><b>${esc(String(a.severity||'Attention').toUpperCase())}${a.tool?' · '+esc(a.tool):''}</b><span>${a.status==='Complete'?'HISTORY':'OPEN'}</span></div><div>${esc(a.text||'')}</div><small>Owner: ${esc(a.owner||'Unassigned')} · Due: ${esc(fmtDate(a.due||''))}${a.sourceMeeting?' · '+esc(a.sourceMeeting):''}${a.completedAt?' · Cleared '+esc(fmtDate(String(a.completedAt).slice(0,10))):''}</small>${a.status!=='Complete'?`<button class="btn" data-actiondone="${esc(a.id)}">CLEAR / COMPLETE</button>`:''}</div>`;return `${centerPageTitle('ACTION CENTER')}<section class="panel action-frame"><div class="summary-grid action-summary"><div class="summary-box critical-box"><span>CRITICAL</span><b>${counts.critical}</b></div><div class="summary-box attention-box"><span>ATTENTION</span><b>${counts.attention}</b></div><div class="summary-box reminder-box"><span>REMINDERS</span><b>${counts.reminder}</b></div><div class="summary-box information-box"><span>INFORMATION</span><b>${counts.information}</b></div></div><div class="action-history-tools"><input id="actionHistorySearch" class="search-box" placeholder="Search action history, tool, owner or text..."></div><div class="action-list">${list.map(card).join('')||'<p>No actions in this view.</p>'}</div></section>`}
function editAction(id){let a=state.actions.find(x=>x.id===id);if(!a)return;modal(`<div class="modal-form"><h2>${a.status==='Complete'?'ACTION HISTORY':'EDIT ACTION'}</h2><div class="form-grid">${selField('Type','ea-severity',selectOptions(['Critical','Attention','Reminder','Information'],a.severity||'Attention'),a.severity||'Attention')}${selField('Related Tool','ea-tool',`<option value="">None</option>${selectOptions(nonArchivedTools().map(t=>t.id),a.tool||'')}`,a.tool||'')}${field('Assigned To','ea-owner',a.owner||'')}${field('Due Date','ea-due',a.due||'','date')}<div class="field span4"><label>Action / Reminder</label><textarea id="ea-text">${esc(a.text||'')}</textarea></div><div class="field span4"><label>Resolution / History Notes</label><textarea id="ea-resolution">${esc(a.resolution||'')}</textarea></div></div><div class="modal-actions"><button class="btn" data-modal-cancel>CANCEL</button>${a.status==='Complete'?`<button class="btn" data-reopen-action="${esc(a.id)}">REOPEN</button><button class="btn danger" data-delete-action="${esc(a.id)}">DELETE PERMANENTLY</button>`:`<button class="btn primary" data-actiondone="${esc(a.id)}">CLEAR / COMPLETE</button>`}<button class="btn save" data-save-action-edit="${esc(a.id)}">SAVE CHANGES</button></div></div>`)}
function referenceDetail(r){modal(`<div class="modal-form reference-detail"><h2>REFERENCE DETAIL</h2><div class="form-grid">${field('Title','er-title',r.title||'')}${selField('Category','er-category',selectOptions(['Troubleshooting','Part Number','Procedure','Shortcut','Options','Checklist','Software','Shipping','Contact','General'],r.category||'General'),r.category||'General')}${field('Part Number','er-part',r.partNumber||'')}${field('Tags','er-tags',r.tags||'')}<div class="field span4"><label>Notes / Reference</label><textarea id="er-notes">${esc(r.notes||'')}</textarea></div><div class="field span4"><label>URL / Network File</label><input id="er-url" value="${esc(r.url||'')}"></div>${selField('Favorite','er-favorite',selectOptions(['No','Yes'],r.favorite?'Yes':'No'),r.favorite?'Yes':'No')}</div><div class="modal-actions"><button class="btn" data-modal-cancel>CANCEL</button><button class="btn danger" data-delete-reference="${esc(r.id)}">DELETE REFERENCE</button><button class="btn save" data-save-reference-edit="${esc(r.id)}">SAVE CHANGES</button></div></div>`)}
function referenceView(){let fav=state.references.filter(r=>r.favorite),recent=state.references.slice(-5).reverse(),groups={};state.references.forEach(r=>(groups[r.category||'General']??=[]).push(r));return `${centerPageTitle('REFERENCE LIBRARY')}<section class="panel"><input id="refSearch" class="search-box" placeholder="Search title, part number, notes or tags..."></section><section class="panel"><div class="reference-group"><h3>★ FAVORITES · ${fav.length}</h3>${fav.map(refRow).join('')||'<p class="muted">No favorites.</p>'}</div><div class="reference-group"><h3>RECENTLY USED · ${recent.length}</h3>${recent.map(refRow).join('')||'<p class="muted">None.</p>'}</div>${Object.entries(groups).map(([g,a])=>`<div class="reference-group"><h3>${esc(g)} · ${a.length} NOTE${a.length===1?'':'S'}</h3>${a.map(refRow).join('')}</div>`).join('')}</section>`}
function refRow(r){return `<div class="ref-row clickrow" data-search-ref="${esc(r.id)}"><b>${r.favorite?'★ ':''}${esc(r.title)}</b><span>${esc(r.tags||'')} ${r.updated?`· Updated ${fmtDate(r.updated)}`:''}</span></div>`}
function archiveView(){let a=state.tools.filter(t=>t.toolStatus==='Archived'),groups={};a.forEach(t=>{let q=t.quarter||t.originalQuarter||'UNKNOWN';(groups[q]??=[]).push(t)});return `${centerPageTitle('ARCHIVE')}<section class="panel"><h2>TOOL ARCHIVE</h2>${Object.keys(groups).sort().reverse().map(q=>`<details class="archive-quarter" open><summary>${esc(q)} · ${groups[q].length} TOOLS</summary><table class="data-table"><thead><tr><th>UTID</th><th>Code Name</th><th>Alias</th><th>Checklist</th><th>Ship</th><th>Customer</th><th>Driver</th></tr></thead><tbody>${groups[q].map(t=>`<tr class="clickrow" data-archived-tool="${esc(t.id)}"><td><b>${esc(t.id)}</b></td><td>${esc(t.codename)}</td><td>${esc(t.alias||'')}</td><td>${esc(checklistLabel(t,t.currentChecklist))}</td><td>${esc(fmtDate(t.shipDate))}</td><td>${esc(t.customer)}</td><td>${esc(t.driver)}</td></tr>`).join('')}</tbody></table></details>`).join('')||'<p>No archived tools yet. Use ADD TOOL TO ARCHIVE to choose an active tool to archive.</p>'}</section>`}

function searchView(){return `${centerPageTitle('SEARCH')}<section class="panel search-frame"><input id="globalSearch" class="search-box" placeholder="SEARCH UTID, CUSTOMER, SALES ORDER, NC, CHECKLIST, NOTES, ACTIONS, MEETINGS, PART NUMBERS..."><div id="searchResults"></div></section>`}
function mysteryCfg(f){let base={title:'MISSION COMPLETE!',headline:'RAAAIDERS!',line1:`ALL ${f.toUpperCase()} SYSTEMS SHIPPED`,line2:'GREAT JOB TEAM!',media:'raiders.jpg',showCount:true};return Object.assign(base,state.config.mystery?.[f]||{})}
function adminView(){return `<section class="panel admin-mode-panel"><h2>COMMAND CENTER MODE</h2><div class="mode-banner ${state.environment==='PRODUCTION'?'production':'test'}">CURRENT MODE: <b>${esc(state.environment)}</b></div><div class="admin-actions"><button class="btn primary" data-admin-mode="production">START / RETURN TO PRODUCTION</button><button class="btn" data-dataset="empty">0 TOOL TEST</button><button class="btn" data-dataset="one">1 TOOL TEST</button><button class="btn" data-dataset="scenario">SCENARIO TEST</button><button class="btn" data-act="export">EXPORT BACKUP</button><button class="btn" id="importJson">RESTORE BACKUP</button><input id="importFile" type="file" accept="application/json" class="hidden"><button class="btn danger" data-master-reset>MASTER RESET</button></div><p class="helper">Production and test data never mix. MASTER RESET creates a completely blank Production Command Center.</p></section><section class="panel"><h2>QUARTER PLANNING STATUS</h2><p class="helper">The PLANNED box remains disabled at 0 until a planned tool count is entered. Pulled In / Pushed Out activate automatically from quarter movement.</p><div class="form-grid"><div class="field"><label>Planned ${esc(state.quarter)} Tool Count</label><input id="admin-planned-count" type="number" min="0" value="${Number(state.config?.plannedCount)||0}"></div></div><div class="admin-actions"><button class="btn save" data-save-planned-count>SAVE PLANNED COUNT</button></div></section><section class="panel"><h2>ACTIVE QUARTER / CYCLE TIME MANAGEMENT</h2><p class="helper">The Active Quarter drives Live Operations totals, statuses, calculations and progress bars. Other quarters with active tools remain available in Tool Center until every tool in that quarter is archived.</p><div class="form-grid"><div class="field span2"><label>Current Active Quarter</label><select id="admin-active-quarter">${selectOptions([...new Set([...quarterChoices(),...activeQuarters()])],state.quarter)}</select></div></div><div class="admin-actions"><button class="btn save" data-save-active-quarter>SAVE ACTIVE QUARTER</button></div><h3>MANAGEMENT AVERAGE FI CYCLE TIME BY TOOL TYPE</h3><div class="cycle-average-grid">${FAMILIES.map(f=>`<label>${esc(f)}<input type="number" min="0" data-cycle-average="${esc(f)}" value="${Number(state.config?.cycleAverages?.[f])||0}" placeholder="Days"></label>`).join('')}</div><div class="admin-actions"><button class="btn save" data-save-cycle-averages>SAVE CYCLE TARGETS</button></div></section><section class="panel"><h2>MYSTERY BOX SETTINGS</h2><div class="mystery-admin-grid">${FAMILIES.map(f=>{let c=mysteryCfg(f);return `<div class="mystery-admin-card" data-mystery-family="${esc(f)}"><h3>${esc(f)}</h3><label>Popup Title<input data-mystery-field="title" value="${esc(c.title)}"></label><label>Headline<input data-mystery-field="headline" value="${esc(c.headline)}"></label><label>Message Line 1<input data-mystery-field="line1" value="${esc(c.line1)}"></label><label>Message Line 2<input data-mystery-field="line2" value="${esc(c.line2)}"></label><label>Media<select data-mystery-field="media">${selectOptions(MYSTERY_MEDIA,c.media)}</select></label><label>Show Count<select data-mystery-field="showCount">${selectOptions(['Yes','No'],c.showCount?'Yes':'No')}</select></label></div>`}).join('')}</div><div class="admin-actions"><button class="btn save" data-save-mystery>SAVE MYSTERY SETTINGS</button></div></section><section class="panel"><h2>TOOL PHOTO MANAGEMENT</h2><p class="helper">Replace the image used for a tool code name everywhere in the Command Center. Images are stored with this browser backup data.</p><div class="tool-photo-admin-grid">${FAMILIES.map(f=>{let custom=!!state.config?.toolPhotos?.[f],src=state.config?.toolPhotos?.[f]||('assets/'+defaultFamilyImageName(f));return `<div class="tool-photo-admin-card"><h3>${esc(f).toUpperCase()}</h3><div class="tool-photo-preview"><img src="${src}" alt="${esc(f)} preview"></div><div class="tool-photo-actions"><label class="btn photo-upload-btn">${custom?'REPLACE PHOTO':'CHOOSE PHOTO'}<input type="file" accept="image/png,image/jpeg,image/webp" data-tool-photo-upload="${esc(f)}" hidden></label><button class="btn" data-tool-photo-reset="${esc(f)}" ${custom?'':'disabled'}>RESTORE DEFAULT</button></div><small>${custom?'CUSTOM PHOTO ACTIVE':'DEFAULT PHOTO'}</small></div>`}).join('')}</div></section><section class="panel"><h2>DATA INTEGRITY</h2>${integrityHtml()}</section>`}
function toolValidationIssues(t){
  let issues=[],req=(label,val)=>{if(val===undefined||val===null||String(val).trim()===''||String(val).trim()==='TBD'||String(val).trim()==='Not Set')issues.push(label)};
  req('UTID / Serial',t.id);req('Code Name',t.codename);req('Model',t.model);req('Current Quarter',t.quarter);req('Tool Status',t.toolStatus);
  if(['FI','Engineering','Powered Down','Packing'].includes(t.toolStatus)){
    req('Customer',t.customer);req('MFG Ship Date',t.shipDate);req('Cleanroom',t.cleanroom);req('Tool Assignment / Driver',t.driver);
    req('Current FI Checklist',t.currentChecklist);req('Micro Schedule Target',t.microSchedule);req('Current Lead / Admin Task',t.currentLeadTask);
    req('Customer Source Required',t.sourceRequired);req('STR Required',t.strRequired);
    if(t.sourceRequired==='Yes')req('Customer Source Status',t.sourceStatus);
    if(t.strRequired==='Yes')req('STR Status',t.strStatus);
  }
  if(t.toolStatus==='Packing')req('Shipping Schedule Status',t.shipping?.scheduleStatus);
  return issues
}
function integrityHtml(){
  let ids={};state.tools.forEach(t=>(ids[t.id]??=[]).push(t));
  let dup=Object.entries(ids).filter(([k,a])=>k&&a.length>1);
  let checked=activeTools(),rows=checked.map(t=>({t,issues:toolValidationIssues(t)})),bad=rows.filter(x=>x.issues.length),missing=bad.reduce((n,x)=>n+x.issues.length,0);
  return `<div class="verify-summary"><div><b>${checked.length}</b><span>TOOLS CHECKED</span></div><div class="${bad.length?'verify-warn':'verify-pass'}"><b>${checked.length-bad.length}</b><span>COMPLETE</span></div><div class="${bad.length?'verify-warn':''}"><b>${bad.length}</b><span>NEED ATTENTION</span></div><div class="${missing?'verify-warn':''}"><b>${missing}</b><span>MISSING / TBD</span></div></div>${dup.length?dup.map(([id,a])=>`<div class="action-card critical"><b>DUPLICATE UTID ${esc(id)}</b> — ${a.length} records</div>`).join(''):'<p class="verify-ok">✓ No duplicate UTIDs detected.</p>'}<div class="verify-tool-list">${bad.map(({t,issues})=>`<div class="verify-tool-card"><div><b>${esc(t.id)} · ${esc(t.codename)} · ${esc(t.model)}</b><span>${issues.length} ITEM${issues.length===1?'':'S'} NEED ATTENTION</span></div><div class="verify-fields">${issues.map(x=>`<span>${esc(x)}</span>`).join('')}</div><button class="btn" data-search-tool="${esc(t.id)}">OPEN TOOL</button></div>`).join('')||'<div class="verify-all-pass">✓ ALL ACTIVE TOOLS PASS THE CURRENT COMPLETENESS CHECK</div>'}</div>`
}
function morningMeetingReady(kind){let weekend=kind==='Weekend';let tools=dailyOrderedTools();return `<section class="panel morning-meeting-ready"><div class="panel-head"><h2>${weekend?'WEEKEND':'WEEKDAY'} MORNING MEETING WORKSPACE</h2><button class="btn primary" data-start-embedded-morning>${findMorningDraft(weekend?'Weekend Morning Meeting':'Weekday Morning Meeting')?'RESUME MORNING MEETING':'START MORNING MEETING'}</button></div>${weekend?`<div class="oncall-preview">ON-CALL MANAGER · MDE · PLANNER fields become active when the meeting starts.</div>`:''}<div class="meeting-ready-list">${tools.map((t,i)=>`<div class="meeting-ready-tool"><b>${i+1}. ${esc(t.id)} · ${esc(t.codename)} · ${esc(t.model)}</b><span>${esc(checklistLabel(t,t.currentChecklist))} · ${esc(t.toolStatus)} · ${esc(fmtDate(t.shipDate))}</span><div class="meeting-placeholder">Tool Meeting Notes · Action Tasks</div></div>`).join('')||'<p>No active tools.</p>'}</div><div class="meeting-placeholder general">GENERAL MEETING NOTES · GENERAL ACTION TASKS</div></section>`}
function updateView(){
  // Tool Editor is a first-class route. Do not infer it from generic Update Center mode.
  if(route.sub==='tool'){
    const isNew=route.toolId==='new';
    if(isNew){
      if(!draft || toolEditorMode!=='create'){
        draft=normalizeTool(defaultTool());
        draft.id='';
        draft.quarter=state.quarter;
        draft.originalQuarter=state.quarter;
        mode='create';
        toolEditorMode='create';
        selected=null;
      }
      return toolForm(draft,true);
    }
    const id=String(route.toolId||selected||'');
    let source=state.tools.find(x=>x.id===id);
    if(!source) return `<section class="panel tool-editor"><h2>TOOL NOT FOUND</h2><p>The selected tool could not be loaded.</p></section>`;
    if(!draft || selected!==id || toolEditorMode!=='edit'){
      draft=clone(source);
      selected=id;
      mode='edit';
      toolEditorMode='edit';
    }
    return toolForm(draft,false);
  }
  if(route.sub==='tools') return toolsDashboard();
  if(route.sub==='daily') return mode==='edit'?dailyForm():`${centerPageTitle('UPDATE COMMAND CENTER')}<section class="panel">${statusEmail('Current')}</section>`;
  return toolsDashboard();
}
function historicalStatusHtml(r){let tools=Array.isArray(r.tools)?r.tools:[];return `<div class="historical-status"><div class="email-meta">${esc(String(r.kind||'MORNING STATUS').toUpperCase())} · ${esc(fmtDate(r.date))} · ${tools.length} SYSTEMS</div>${tools.map(t=>{let ncs=(t.ncs||[]).filter(n=>n.state!=='Closed');return `<div class="email-row"><div class="email-main">${esc(t.id)} (${esc(t.cleanroom||'')}${t.bay?' / '+esc(t.bay):''}) (${esc(t.model||'')} - ${esc(t.codename||'')}) ${esc(checklistLabel(t,t.currentChecklist||''))} (${esc(t.customer||'')}, ${esc(fmtDate(t.shipDate||''))}) <span class="lamp-hours">(Lamp Hours: ${Number(t.lamp)||0}${String(t.lampState||'').toUpperCase()==='OFF'?' - OFF':''})</span></div><div class="email-subline">- ${esc(t.latestStatus||'No latest status entered.')}</div>${ncs.map(n=>`<div class="email-subline">- ${displayNcId(n.id)}: ${esc(n.description||'')}</div>${n.poa?`<div class="email-subline">- POA: ${esc(n.poa)}</div>`:''}`).join('')}</div>`}).join('')}</div>`}
function openStatusRecord(id){let r=state.statusRecords.find(x=>x.id===id);if(!r)return;modal(`<div class="historical-status-modal"><h2>READ-ONLY STATUS HISTORY</h2>${historicalStatusHtml(r)}<div class="modal-actions"><button class="btn" data-modal-cancel>BACK TO HISTORY</button></div></div>`)}
const VIEWS={operations:()=>route.sub==='tools'?toolsDashboard():route.sub==='tool'?updateView():route.sub==='daily'?(mode==='edit'?dailyForm():`${centerPageTitle('UPDATE COMMAND CENTER')}<section class="panel">${statusEmail('Current')}</section>`):route.sub==='archive'?archiveView():(document.body.classList.contains('presentation-mode')?`${presentationQuarterPanel()}<div class="presentation-tool-only">${liveToolCard()}</div>`:quarterPanel()+`<div class="operations-dual-grid"><div class="operations-status-carousel">${statusSnapshot()}</div><div class="operations-tool-carousel">${liveToolCard()}</div></div>`),shipping:()=>mode==='edit'?shippingEdit():shippingView(false),priority:()=>mode==='edit'?priorityEdit(route.sub):priorityView(route.sub),status:()=>route.sub==='history'?`<section class="panel status-history-frame">${state.meetings.filter(m=>/Morning Meeting/i.test(m.type||'')).map(m=>`<div class="ref-row clickrow" data-search-meeting="${esc(m.id)}"><b>${esc(m.type)} · ${esc(fmtDate(m.date))}</b><span>${(m.toolOrder?.length||m.toolSnapshots?.length||0)} tools · OPEN MEETING</span></div>`).join('')||'<p>No morning meeting history.</p>'}</section>`:`${centerPageTitle((route.sub==='weekend'?'WEEKEND':'WEEKDAY')+' MORNING STATUS')}<div class="status-center-stack"><section class="panel status-workspace">${statusEmail(route.sub==='weekend'?'Weekend':'Weekday')}</section><div class="meeting-workspace-wrap">${mode==='morningMeeting'&&meetingDraft?morningMeetingForm(meetingDraft):morningMeetingReady(route.sub==='weekend'?'Weekend':'Weekday')}</div></div>`,meeting:()=>mode==='meeting'?meetingForm(meetingDraft):route.sub==='history'?meetingHistory():meetingHistory({leads:'Leads Meeting',orb:'ORB Meeting',cell:'Cell Meeting',escalation:'Escalation Meeting'}[route.sub]||''),action:()=>actionView(),reference:()=>referenceView(),cycle:()=>`${centerPageTitle('FI CYCLE TIME STATUS')}${cycleTimeView()}`,search:()=>searchView(),admin:()=>route.sub==='audit'?`${centerPageTitle('DATA INTEGRITY · VERIFY TOOLS')}<section class="panel"><h2>VERIFY TOOLS</h2><p class="helper">Checks the current quarter for duplicate UTIDs and phase-appropriate required fields. On/Off badges are valid in either state and are not treated as missing.</p>${integrityHtml()}</section>`:adminView()};
function beginEdit(){if(route.center==='operations'){let origin=clone(route);if(route.sub==='daily'){returnRoute=origin;dailyContext='weekday';mode='edit';draft=clone(state.tools);dirty=false;return render()}if(route.sub==='priorities'){returnRoute=origin;route={center:'priority',sub:'weekday'};mode='edit';dirty=false;return render()}if(route.sub==='schedule'){returnRoute=origin;route={center:'shipping',sub:'home'};mode='edit';dirty=false;return render()}}if(route.center==='operations'&&route.sub==='daily'){returnRoute=null;dailyContext='weekday';mode='edit';draft=clone(state.tools)}else if(route.center==='shipping'){returnRoute=null;mode='edit'}else if(route.center==='priority'){returnRoute=null;mode='edit'}else if(route.center==='status'){returnRoute=clone(route);dailyContext=route.sub==='weekend'?'weekend':'weekday';route={center:'operations',sub:'daily'};mode='edit';draft=clone(state.tools)}else if(route.center==='action'){mode='edit'}else if(route.center==='reference'){mode='edit'}dirty=false;render()}
function renderToolEditorPage(){
  allRules();
  shell();
  const app=document.querySelector('#app');
  if(route.center!=='operations'||route.sub!=='tool'){return render();}
  const isNew=route.toolId==='new';
  if(isNew){
    if(!draft){draft=normalizeTool(defaultTool());draft.id='';draft.quarter=state.quarter;draft.originalQuarter=state.quarter;}
    mode='create';toolEditorMode='create';selected=null;
    try{app.innerHTML=toolForm(draft,true)}catch(err){console.error('Tool editor render failed',err);app.innerHTML=`<section class="panel tool-editor editor-error"><h2>TOOL EDITOR ERROR</h2><p>${esc(err.message||String(err))}</p></section>`;}
  }else{
    const id=String(route.toolId||selected||'');
    const t=state.tools.find(x=>x.id===id);
    if(!t){app.innerHTML=`<section class="panel tool-editor"><h2>TOOL NOT FOUND</h2><p>${esc(id)}</p></section>`;}
    else{
      if(!draft||selected!==id){draft=clone(t);selected=id;}
      mode='edit';toolEditorMode='edit';
      try{app.innerHTML=toolForm(draft,false)}catch(err){console.error('Tool editor render failed',err);app.innerHTML=`<section class="panel tool-editor editor-error"><h2>TOOL EDITOR ERROR</h2><p>${esc(err.message||String(err))}</p></section>`;}
    }
  }
  bindInputs();
  bindCoreInteractions();
}
function addTool(){
  const origin=clone(route);
  returnRoute=(origin.center==='operations'&&origin.sub==='tools')?{center:'operations',sub:'tools'}:origin;
  draft=normalizeTool(defaultTool());
  draft.id='';
  draft.quarter=state.quarter;
  draft.originalQuarter=state.quarter;
  selected=null;
  mode='create';
  toolEditorMode='create';
  dirty=false;
  route={center:'operations',sub:'tool',toolId:'new'};
  renderToolEditorPage();
  requestAnimationFrame(()=>{window.scrollTo(0,0);document.querySelector('.tool-editor')?.focus();});
}
function openTool(id){
  id=String(id||'');
  const t=state.tools.find(x=>x.id===id);
  if(!t){toast('TOOL NOT FOUND');return;}
  const origin=clone(route);
  returnRoute=(origin.center==='operations'&&origin.sub==='tools')?{center:'operations',sub:'tools'}:origin;
  selected=id;
  draft=clone(t);
  mode='edit';
  toolEditorMode='edit';
  dirty=false;
  route={center:'operations',sub:'tool',toolId:id};
  renderToolEditorPage();
  requestAnimationFrame(()=>{window.scrollTo(0,0);document.querySelector('.tool-editor')?.focus();});
}
function captureDailyEditor(){
  let ids=[];
  [...document.querySelectorAll('[data-daily]')].forEach(r=>{
    let t=state.tools.find(x=>x.id===r.dataset.daily);
    if(!t)return;
    ids.push(t.id);
    collectScopedToolForm(t,r,r.dataset.prefix);
  });
  if(ids.length)state.config.dailyOrder=ids;
  return ids;
}
function saveCurrent(){if(route.center==='operations'&&route.sub==='tool'&&draft&&(mode==='create'||mode==='edit')){let t=draft;collectToolForm(t);if(!t.id)return alert('UTID / Serial is required.');let duplicate=state.tools.find(x=>x.id.toLowerCase()===t.id.toLowerCase()&&x.id!==selected);if(duplicate)return alert(`DUPLICATE TOOL — ${t.id} already exists. Open the existing tool instead.`);if(mode==='create')state.tools.push(normalizeTool(t));else{let i=state.tools.findIndex(x=>x.id===selected);if(i>=0)state.tools[i]=normalizeTool(t)}saveState(mode==='create'?`TOOL ${t.id} ADDED`:`TOOL ${t.id} SAVED`);mode='view';toolEditorMode='view';draft=null;selected=null;let dest=returnRoute;returnRoute=null;route=dest||{center:'operations',sub:'tools'};render();return}
 if(mode==='edit'&&route.center==='operations'&&route.sub==='daily'){captureDailyEditor();let snap={id:`${dailyContext}-${today()}`,kind:dailyContext==='weekend'?'Weekend Morning Status':'Weekday Morning Status',date:today(),savedAt:nowISO(),tools:clone(dailyOrderedTools())};let si=state.statusRecords.findIndex(x=>x.id===snap.id);if(si>=0)state.statusRecords[si]=snap;else state.statusRecords.unshift(snap);saveState('COMMAND CENTER UPDATES SAVED');mode='view';draft=null;dirty=false;let dest=returnRoute;returnRoute=null;route=dest||{center:'operations',sub:'live'};render();return}
 if(mode==='edit'&&route.center==='priority'){let list=[];document.querySelectorAll('[data-priority]').forEach(r=>{let v=f=>r.querySelector(`[data-pf="${f}"]`)?.value||'',tool=state.tools.find(t=>t.id===r.dataset.priority),p=Number(v('priority'));if(tool){tool.salesOrder=v('salesOrder');tool.customer=v('customer');tool.shipDate=v('shipDate');tool.cleanroom=v('cleanroom');tool.driver=v('assignment')||tool.driver}if(p)list.push({tool:r.dataset.priority,priority:p,assignment:v('assignment'),notes:v('notes')})});state.priorities[route.sub]=list;state.priorityMeta[route.sub].anchor=document.querySelector('#priorityAnchor')?.value||state.priorityMeta[route.sub].anchor||today();if(route.sub==='weekend'){for(let day of ['saturday','sunday'])state.priorityMeta.weekend[day]=[...document.querySelectorAll(`[data-volunteer^="${day}-"]`)].map(r=>({name:r.querySelector('[data-vf="name"]')?.value||'',hours:r.querySelector('[data-vf="hours"]')?.value||'',notes:r.querySelector('[data-vf="notes"]')?.value||''}))}saveState(`${route.sub.toUpperCase()} PRIORITIES SAVED`);mode='view';let dest=returnRoute;returnRoute=null;route=dest||route;render();return}
 if(mode==='edit'&&route.center==='shipping'){document.querySelectorAll('[data-shipping]').forEach(r=>{let t=state.tools.find(x=>x.id===r.dataset.shipping);if(!t)return;let v=f=>r.querySelector(`[data-sf="${f}"]`)?.value||'';t.shipping.scheduleStatus=v('scheduleStatus');t.shipping.scheduleSent=v('scheduleSent')==='Yes';t.shipping.notes=v('notes');t.shipping.completed=t.shipping.completed||{};r.querySelectorAll('[data-ms-plan]').forEach(el=>t.shipping[el.dataset.msPlan]=el.value||'');r.querySelectorAll('[data-ms-actual]').forEach(el=>t.shipping.completed[el.dataset.msActual]=el.value||'');r.querySelectorAll('[data-ms-complete]').forEach(el=>{let k=el.dataset.msComplete;if(!el.checked)t.shipping.completed[k]='';else if(!t.shipping.completed[k])t.shipping.completed[k]=today()});applyRules(t)});saveState('SHIPPING SCHEDULES SAVED');mode='view';let dest=returnRoute;returnRoute=null;route=dest||{center:'shipping',sub:'home'};render();return}
 if(mode==='morningMeeting')return saveMorningMeeting(false);if(mode==='meeting')return saveMeeting(false);toast('NO EDITABLE CHANGES ON THIS PAGE')}
function saveMeeting(end){captureMeetingForm();let m=meetingDraft;if(m.type==='Escalation Meeting'&&m.tool){let t=state.tools.find(x=>x.id===m.tool);if(t){let n=t.ncs.find(x=>x.id===m.nc)||t.ncs[0];if(n&&m.poa){n.poa=m.poa;if(n.state==='Open')n.state='Escalated'}t.latestStatus=m.notes||t.latestStatus}}if(end){let meetingId=uid('mtg'),saved={...clone(m),id:meetingId,endedAt:nowISO()};state.meetings.unshift(saved);(m.tasks||[]).filter(x=>x.text).forEach(task=>state.actions.push({id:uid('act'),sourceMeetingId:meetingId,sourceTaskId:task.id,severity:m.type==='Escalation Meeting'?'Critical':'Attention',tool:m.tool||'',text:task.text,owner:task.owner,due:task.due,status:'Open',createdAt:nowISO()}));saveState('MEETING ENDED — MINUTES AND TASKS SAVED');mode='view';meetingDraft=null;route={center:'meeting',sub:'history'};render()}else{toast('✓ MEETING DRAFT UPDATED — ACTIONS CREATE WHEN MEETING ENDS')}}

